const text = stdin.replace(/\r\n/g, '\n');
const blank = text.indexOf('\n\n');
const head = blank === -1 ? text.replace(/\n+$/, '') : text.slice(0, blank);
const body = blank === -1 ? '' : text.slice(blank + 2).replace(/\n+$/, '');
const lines = head.split('\n');
const parts = lines[0].trim().split(/\s+/);
if (parts.length !== 3 || !/^HTTP\/[0-9]/.test(parts[2])) {
  console.log('400 Bad Request');
} else {
  const method = parts[0];
  const target = parts[1];
  const q = target.indexOf('?');
  const path = q === -1 ? target : target.slice(0, q);
  const query = q === -1 ? '' : target.slice(q + 1);
  const pairs = query.split('&').filter(Boolean).map(p => {
    const i = p.indexOf('=');
    if (i === -1) return p + '=';
    return p.slice(0, i) + '=' + decodeURIComponent(p.slice(i + 1).replace(/\+/g, ' '));
  });
  const headers = {};
  for (const line of lines.slice(1)) {
    const i = line.indexOf(':');
    if (i > 0) headers[line.slice(0, i).trim().toLowerCase()] = line.slice(i + 1).trim();
  }
  console.log('METHOD ' + method);
  console.log('PATH ' + path);
  console.log('QUERY ' + (pairs.length ? pairs.join('; ') : 'none'));
  console.log('HOST ' + (headers['host'] || 'missing'));
  console.log('CONTENT-TYPE ' + (headers['content-type'] || 'none'));
  console.log('BODY ' + body.length);
}
